// Extract webhook input and split into geo_context (Layer 1) and strategy_context (Layer 2 only)
const input = $json.body || $json;

// geo_context: ONLY geographic identifiers — forwarded to all 5 agents
const geo_context = {
  zip_code: input.zip_code || '63365',
  city: input.city || 'Unknown',
  county: input.county || 'Unknown',
  state: input.state || 'Unknown'
};

// strategy_context: investment parameters — held for Layer 2 synthesis ONLY
const strategy_context = {
  exit_strategy: input.exit_strategy || 'Fix & Flip',
  buy_box_criteria: input.buy_box_criteria || {}
};

return {
  geo_context: geo_context,
  strategy_context: strategy_context
};

// Collect all 5 agent responses - use .first() for parallel merge compatibility
const geo = $('Extract Input').first().json.geo_context;
const strategy = $('Extract Input').first().json.strategy_context;
const agent1 = $('Agent 1: Property Stock').first().json.choices?.[0]?.message?.content || '{}';
const agent2 = $('Agent 2: Financial & Equity').first().json.choices?.[0]?.message?.content || '{}';
const agent3 = $('Agent 3: Distress & Legal').first().json.choices?.[0]?.message?.content || '{}';
const agent4 = $('Agent 4: Ownership & Occupancy').first().json.choices?.[0]?.message?.content || '{}';
const agent5 = $('Agent 5: Market Dynamics').first().json.choices?.[0]?.message?.content || '{}';

// Build Layer 2 Analyst Prompt — NOW pulls strategy_context for the first time
const layer2Prompt = `You are a real estate market analyst synthesizing intelligence for ${geo.zip_code} in ${geo.city}, ${geo.county}, ${geo.state} through the lens of a ${strategy.exit_strategy} investment strategy.

You have received 5 independent research reports from strategy-blind agents. Your job is to apply mosaic theory: connect patterns across these reports that no single agent could have identified alone, then assess whether this zip presents HIGH or LOW signal for the specified exit strategy.

## INPUT DATA

### CLIENT EXIT STRATEGY:
${strategy.exit_strategy}

### CLIENT BUY BOX CRITERIA:
${JSON.stringify(strategy.buy_box_criteria, null, 2)}

### RESEARCH REPORT 1: Property Stock Analyst
${agent1}

### RESEARCH REPORT 2: Financial & Equity Analyst
${agent2}

### RESEARCH REPORT 3: Distress & Legal Analyst
${agent3}

### RESEARCH REPORT 4: Ownership & Occupancy Analyst
${agent4}

### RESEARCH REPORT 5: Market Dynamics & Momentum Analyst
${agent5}

## YOUR TASK: MOSAIC SYNTHESIS

Connect patterns ACROSS reports. Look for:
- Death + Absentee + Equity patterns
- Foreclosure + Portfolio + ARM patterns  
- Renovation catalyst patterns
- Teardown opportunity patterns

Apply the ${strategy.exit_strategy} lens to assess relevance.

Note: Some agents may report data at county level or note data scarcity. Factor data confidence into your assessment. If most data is county-level for a small/rural zip, lower your confidence score accordingly.

Classify as HIGH SIGNAL or LOW SIGNAL with confidence score (0.0-1.0).

## OUTPUT SCHEMA (Return ONLY valid JSON):

{
  "zip_code": "${geo.zip_code}",
  "city": "${geo.city}",
  "county": "${geo.county}",
  "state": "${geo.state}",
  "exit_strategy": "${strategy.exit_strategy}",
  "signal_classification": "HIGH or LOW",
  "confidence": 0.0 to 1.0,
  "data_quality_notes": "Note any data scarcity or county-level aggregation issues",
  "dominant_profiles": ["heirs", "absentee_out_of_state", "equity_rich", "aging_owners"],
  "observed_combinations": [
    {
      "name": "Combination name",
      "prevalence": "high/moderate/low",
      "evidence": "Agent X reported Y",
      "signal_strength": "strong/moderate/weak",
      "relevance_to_strategy": "Why this matters for ${strategy.exit_strategy}"
    }
  ],
  "median_value": 285000,
  "lat": 38.7123,
  "lng": -90.8845,
  "insight": "2-3 sentence client-facing summary",
  "reasoning": "Detailed synthesis showing how you connected patterns across reports"
}

Output ONLY the JSON. No markdown fences, no explanatory text.`;

// Return for Claude call
return {
  model: 'claude-opus-4-5-20251101',
  max_tokens: 8000,
  temperature: 0.1,
  messages: [{ role: 'user', content: layer2Prompt }]
};

// Parse Layer 2 output
const claudeResponse = $json.content?.[0]?.text || '{}';

// Clean JSON if wrapped in markdown
let cleanedResponse = claudeResponse;
if (claudeResponse.includes('```json')) {
  const match = claudeResponse.match(/```json\s*([\s\S]*?)\s*```/);
  if (match) cleanedResponse = match[1];
}

// Parse and return
try {
  const layer2Output = JSON.parse(cleanedResponse);
  return layer2Output;
} catch (e) {
  return {
    error: 'Failed to parse Layer 2 output',
    raw: cleanedResponse.substring(0, 500)
  };
}
